use casbin::prelude::*;
use std::sync::Arc;
use tokio::sync::RwLock;

let enforcer = Arc::new(RwLock::new(
    Enforcer::new("rbac_model.conf", "rbac_policy.csv").await?,
));

async fn authorize(e: &Arc<RwLock<Enforcer>>, sub: &str, obj: &str, act: &str) -> bool {
    e.read().await.enforce((sub, obj, act)).unwrap_or(false)   // error -> deny
}
